<?php
declare(strict_types=1);

function role_label(string $role): string { return ['administrador'=>'Administrador','usuario'=>'Usuario','gestor'=>'Gestor','diretoria'=>'Diretoria','coordenacao_ti'=>'Coordenacao TI','financeiro'=>'Financeiro','rh'=>'RH'][$role] ?? $role; }
function purchase_status_label(string $status): string { return ['PENDING_IT'=>'Pendente na Coordenacao TI','PENDING_FINANCE'=>'Pendente no Financeiro','REJECTED'=>'Rejeitada','PURCHASED'=>'Comprada'][$status] ?? $status; }
function purchase_status_badge(string $status): string { $c=['PENDING_IT'=>'info','PENDING_FINANCE'=>'primary','REJECTED'=>'danger','PURCHASED'=>'success'][$status] ?? 'secondary'; return '<span class="badge text-bg-'.$c.'">'.e(purchase_status_label($status)).'</span>'; }
function inventory_is_active(): bool { return (bool) db()->query("SELECT 1 FROM inventory_sessions WHERE status = 'OPEN' LIMIT 1")->fetchColumn(); }
function require_inventory_unlocked(string $returnPage): void { if (inventory_is_active()) { $_SESSION['flash']='Operacao bloqueada: ha um inventario em andamento.'; redirect($returnPage); } }

function hiring_status_badge(string $status): string { return render_status_badge($status); }
function hiring_transition(int $id, string $next): void { $allowed=['Aprovada','Recusada']; if(!in_array($next,$allowed,true)) throw new RuntimeException('Status invalido.'); db()->prepare('UPDATE hiring_requests SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status=?')->execute([$next,current_user()['id']??null,$id,'Em análise']); }
function purchase_audit(int $id, string $event, string $comments = ''): void { db()->prepare('INSERT INTO purchase_request_audit (purchase_request_id,user_id,event,comments) VALUES (?,?,?,?)')->execute([$id,current_user()['id'] ?? null,$event,$comments ?: null]); }
function purchase_transition(int $id, string $expected, string $next, array $fields, string $event, string $comments): void { $sets=['status = ?']; $values=[$next]; foreach ($fields as $column=>$value) { $sets[]="$column = ?"; $values[]=$value; } $values[]=$id; $values[]=$expected; $stmt=db()->prepare('UPDATE purchase_requests SET '.implode(', ',$sets).' WHERE id = ? AND status = ?'); $stmt->execute($values); if (!$stmt->rowCount()) throw new RuntimeException('Esta solicitacao nao esta disponivel para esta etapa.'); purchase_audit($id,$event,$comments); }

function nova_handle_action(string $page): bool {
    if ($page === 'stock-info') {
        $id=(int)($_GET['ativo_id']??0); require_ativo_no_escopo($id, 'movimentacoes');
        $s=db()->prepare('SELECT quantidade_atual,estoque_minimo,estoque_maximo FROM ativos WHERE id=?'); $s->execute([$id]);
        $r=$s->fetch()?:['quantidade_atual'=>0,'estoque_minimo'=>0,'estoque_maximo'=>0]; $r['reserved']=0; $r['available']=$r['quantidade_atual']; header('Content-Type: application/json; charset=utf-8'); echo json_encode($r); exit;
    }
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') return false;
    if ($page === 'user-save') {
        if (current_profile() !== 'administrador') redirect('dashboard');
        $id=(int)($_POST['id']??0); $role=$_POST['perfil']??''; $roles=['administrador','usuario','gestor','diretoria','coordenacao_ti','financeiro','rh'];
        if (!in_array($role,$roles,true) || trim($_POST['nome']??'')==='' || trim($_POST['email']??'')==='') { $_SESSION['flash']='Preencha nome, e-mail e perfil.'; redirect('usuarios'); }
        try { if($id) { $sql='UPDATE usuarios SET nome=?,email=?,perfil=?,cpf=?,matricula=?,departamento=?,funcao=?'.(trim($_POST['senha']??'')!==''?',senha=?':'').' WHERE id=?'; $v=[trim($_POST['nome']),trim($_POST['email']),$role,trim($_POST['cpf']),trim($_POST['matricula']),trim($_POST['departamento']),trim($_POST['funcao'])]; if(trim($_POST['senha']??'')!=='')$v[]=password_hash($_POST['senha'],PASSWORD_DEFAULT); $v[]=$id; db()->prepare($sql)->execute($v); $_SESSION['flash']='Usuario atualizado.'; } else { if(trim($_POST['senha']??'')==='') throw new RuntimeException('Informe a senha do novo usuario.'); db()->prepare('INSERT INTO usuarios (nome,email,senha,perfil,cpf,matricula,departamento,funcao) VALUES (?,?,?,?,?,?,?,?)')->execute([trim($_POST['nome']),trim($_POST['email']),password_hash($_POST['senha'],PASSWORD_DEFAULT),$role,trim($_POST['cpf']),trim($_POST['matricula']),trim($_POST['departamento']),trim($_POST['funcao'])]); $_SESSION['flash']='Usuario criado.'; } } catch(Throwable $e) { $_SESSION['flash']=$e->getMessage(); }
        redirect('usuarios');
    }
    if ($page === 'purchase-request-save') {
        if(current_profile() !== 'administrador') redirect('dashboard');
        $name=trim($_POST['product_name']??''); $justification=trim($_POST['justification']??''); $priority=$_POST['priority']??'Normal';
        if($name==='' || $justification==='' || !in_array($priority,['Baixa','Normal','Alta','Urgente'],true)) { $_SESSION['flash']='Informe produto, justificativa e prioridade validos.'; redirect('purchase-requests'); }
        db()->beginTransaction(); try { $code=next_code('purchase_requests','request_code','PR'); db()->prepare('INSERT INTO purchase_requests (request_code,requester_id,product_name,quantity,purchase_url,priority,justification,status) VALUES (?,?,?,?,?,?,?,?)')->execute([$code,current_user()['id'],$name,max(1,(int)($_POST['quantity']??1)),trim($_POST['purchase_url']??'') ?: null,$priority,$justification,'PENDING_IT']); $id=(int)db()->lastInsertId(); purchase_audit($id,'Solicitacao criada','Solicitacao criada pelo Administrador e enviada a Coordenacao TI.'); db()->commit(); $_SESSION['flash']='Solicitacao '.$code.' enviada a Coordenacao TI.'; } catch(Throwable $e) { if(db()->inTransaction()) db()->rollBack(); $_SESSION['flash']=$e->getMessage(); }
        redirect('purchase-requests');
    }
    if ($page === 'purchase-it-review') {
        if(current_profile() !== 'coordenacao_ti') redirect('dashboard'); $id=(int)($_POST['id']??0); $approve=($_POST['decision']??'')==='approve'; $comments=trim($_POST['comments']??'');
        if($comments==='') { $_SESSION['flash']='Informe um comentario para registrar a decisao.'; redirect('it-dashboard'); }
        db()->beginTransaction(); try { purchase_transition($id,'PENDING_IT',$approve?'PENDING_FINANCE':'REJECTED',['it_by'=>current_user()['id'],'it_at'=>date('Y-m-d H:i:s'),'it_comments'=>$comments],$approve?'Aprovada pela Coordenacao TI':'Rejeitada pela Coordenacao TI',$comments); db()->commit(); $_SESSION['flash']='Solicitacao avaliada.'; } catch(Throwable $e) { if(db()->inTransaction())db()->rollBack(); $_SESSION['flash']=$e->getMessage(); } redirect('it-dashboard');
    }
    if ($page === 'purchase-complete') {
        if(current_profile() !== 'financeiro') redirect('dashboard'); $id=(int)($_POST['id']??0); $comments=trim($_POST['comments']??''); $supplier=trim($_POST['supplier']??''); $invoice=trim($_POST['invoice_number']??''); $date=$_POST['purchase_date']??'';
        if($supplier==='' || $invoice==='' || $date==='') { $_SESSION['flash']='Informe fornecedor, nota fiscal e data da compra.'; redirect('finance-dashboard'); }
        db()->beginTransaction(); try { purchase_transition($id,'PENDING_FINANCE','PURCHASED',['finance_by'=>current_user()['id'],'finance_at'=>date('Y-m-d H:i:s'),'finance_comments'=>$comments ?: null,'supplier'=>$supplier,'invoice_number'=>$invoice,'purchase_date'=>$date],'Compra concluida pelo Financeiro',$comments); db()->commit(); $_SESSION['flash']='Compra concluida. A solicitacao agora esta somente para consulta.'; } catch(Throwable $e) { if(db()->inTransaction())db()->rollBack(); $_SESSION['flash']=$e->getMessage(); } redirect('finance-dashboard');
    }
    if ($page === 'concluir-requisicao-ti') {
        if (current_profile() !== 'coordenacao_ti') redirect('dashboard');
        $id = (int) ($_POST['id'] ?? 0);
        try {
            concluir_requisicao_estoque($id);
            $_SESSION['flash'] = 'Requisicao concluida, estoque baixado e historico registrado.';
        } catch (Throwable $e) {
            $_SESSION['flash'] = $e->getMessage();
        }
        redirect('requisicoes-ti');
    }
    if ($page === 'hiring-save') {
        if(current_profile() !== 'rh') redirect('dashboard');
        $position=trim($_POST['position']??''); $department=trim($_POST['department']??''); $names=array_values(array_filter(array_map('trim', $_POST['person_name'] ?? []), fn($name)=>$name!=='')); $quantity=count($names); $dataInicio=trim($_POST['data_inicio']??'') ?: null;
        if($position==='' || $department==='' || $quantity<1) { $_SESSION['flash']='Informe cargo, departamento e ao menos uma pessoa para contratacao.'; redirect('hiring'); }
        if($dataInicio===null) { $_SESSION['flash']='Informe a data de inicio.'; redirect('hiring'); }
        $dataInicioObj = DateTime::createFromFormat('Y-m-d', $dataInicio);
        if(!$dataInicioObj) { $_SESSION['flash']='Data de inicio invalida.'; redirect('hiring'); }
        $minDate = (new DateTime('today'))->modify('+7 days');
        if($dataInicioObj < $minDate) { $_SESSION['flash']='A data de inicio deve ter pelo menos 1 semana de antecedencia (a partir de '.$minDate->format('d/m/Y').').'; redirect('hiring'); }
        try { $doc=upload_file('admission_document',['pdf','docx'],'uploads/hiring'); db()->prepare('INSERT INTO hiring_requests (position,department,quantity,candidate_names,data_inicio,admission_document,status,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$position,$department,$quantity,json_encode($names, JSON_UNESCAPED_UNICODE),$dataInicio,$doc,'Em análise',current_user()['id']]); $_SESSION['flash']='Solicitacao de contratacao enviada ao Administrador.'; } catch(Throwable $e) { $_SESSION['flash']=$e->getMessage(); }
        redirect('hiring');
    }
    if ($page === 'hiring-review') {
        if(current_profile() !== 'administrador') redirect('dashboard');
        $id=(int)($_POST['id']??0); $decision=$_POST['decision']??'';
        try { hiring_transition($id,$decision==='approve'?'Aprovada':'Recusada'); $_SESSION['flash']='Solicitacao avaliada.'; } catch(Throwable $e) { $_SESSION['flash']=$e->getMessage(); }
        redirect('hiring');
    }
    if($page==='inventory-start') { if(current_profile()!=='administrador')redirect('dashboard'); db()->beginTransaction(); try { if(inventory_is_active())throw new RuntimeException('Ja existe inventario em andamento.'); db()->prepare("INSERT INTO inventory_sessions (started_by,status) VALUES (?,'OPEN')")->execute([current_user()['id']]); $s=(int)db()->lastInsertId(); db()->prepare('INSERT INTO inventory_balances (inventory_session_id,ativo_id,opening_stock,balance) SELECT ?,id,quantidade_atual,-quantidade_atual FROM ativos')->execute([$s]); db()->commit(); $_SESSION['flash']='Inventario iniciado.'; }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$_SESSION['flash']=$e->getMessage();}redirect('inventory'); }
    if($page==='inventory-scan') { if(current_profile()!=='administrador')redirect('dashboard'); db()->beginTransaction(); try { $s=db()->query("SELECT id FROM inventory_sessions WHERE status='OPEN' FOR UPDATE")->fetch(); $q=db()->prepare('SELECT id FROM ativos WHERE codigo=?'); $q->execute([trim($_POST['asset_code']??'')]); $a=$q->fetch(); if(!$s||!$a)throw new RuntimeException('Inventario ou ativo nao encontrado.'); db()->prepare('INSERT INTO inventory_scans (inventory_session_id,ativo_id,scanned_by) VALUES (?,?,?)')->execute([$s['id'],$a['id'],current_user()['id']]); db()->prepare('UPDATE inventory_balances SET balance=balance+1,counted=counted+1 WHERE inventory_session_id=? AND ativo_id=?')->execute([$s['id'],$a['id']]); db()->commit(); $_SESSION['flash']='Leitura registrada.'; }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$_SESSION['flash']=$e->getMessage();}redirect('inventory'); }
    if($page==='inventory-finish') { if(current_profile()!=='administrador')redirect('dashboard'); db()->beginTransaction(); try { $s=db()->query("SELECT id FROM inventory_sessions WHERE status='OPEN' FOR UPDATE")->fetch(); if(!$s)throw new RuntimeException('Nenhum inventario em andamento.'); $q=db()->prepare('SELECT COUNT(*) FROM inventory_balances WHERE inventory_session_id=? AND balance<>0'); $q->execute([$s['id']]); if((int)$q->fetchColumn())throw new RuntimeException('Todos os saldos devem estar em zero.'); db()->prepare("UPDATE inventory_sessions SET status='FINISHED',finished_by=?,finished_at=NOW() WHERE id=?")->execute([current_user()['id'],$s['id']]); db()->commit(); $_SESSION['flash']='Inventario finalizado.'; }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$_SESSION['flash']=$e->getMessage();}redirect('inventory'); }
    return false;
}
function purchase_rows(?array $statuses=null): array { $sql='SELECT pr.*,u.nome requester_name,u.departamento FROM purchase_requests pr JOIN usuarios u ON u.id=pr.requester_id'; $p=[]; if($statuses){$sql.=' WHERE pr.status IN ('.implode(',',array_fill(0,count($statuses),'?')).')';$p=$statuses;} $sql.=' ORDER BY pr.id DESC'; $s=db()->prepare($sql);$s->execute($p);return $s->fetchAll(); }
function purchase_timeline(int $id): string { $s=db()->prepare('SELECT a.event,a.comments,a.created_at,u.nome AS usuario FROM purchase_request_audit a LEFT JOIN usuarios u ON u.id=a.user_id WHERE a.purchase_request_id=? ORDER BY a.id');$s->execute([$id]);ob_start();table_view($s->fetchAll(),'Sem eventos.');return ob_get_clean(); }
function nova_render_page(string $page,?string $flash): bool {
 $profile=current_profile();
 if($page==='usuarios'){if($profile!=='administrador')redirect('dashboard');$edit=null;if(!empty($_GET['id'])){$s=db()->prepare('SELECT * FROM usuarios WHERE id=?');$s->execute([(int)$_GET['id']]);$edit=$s->fetch();}$rows=db()->query('SELECT id,nome,email,perfil,departamento,funcao FROM usuarios ORDER BY nome')->fetchAll();echo '<h1>Usuarios</h1>'.($flash?'<div class="alert-success">'.e($flash).'</div>':'').'<section class="grid2"><form class="card asset-form" method="post" action="index.php?page=user-save"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="id" value="'.e($edit['id']??'').'"><h2>'.($edit?'Editar usuario':'Novo usuario').'</h2><label>Nome<input name="nome" required value="'.e($edit['nome']??'').'"></label><label>E-mail<input type="email" name="email" required value="'.e($edit['email']??'').'"></label><label>Perfil<select name="perfil">';foreach(['administrador','usuario','gestor','diretoria','coordenacao_ti','financeiro','rh'] as $r)echo '<option value="'.$r.'" '.(($edit['perfil']??'usuario')===$r?'selected':'').'>'.e(role_label($r)).'</option>';echo '</select></label><label>Senha'.($edit?' (em branco mantem a atual)':'').'<input type="password" name="senha" '.($edit?'':'required').'></label><label>CPF<input name="cpf" value="'.e($edit['cpf']??'').'"></label><label>Matricula<input name="matricula" value="'.e($edit['matricula']??'').'"></label><label>Departamento<input name="departamento" value="'.e($edit['departamento']??'').'"></label><label>Funcao<input name="funcao" value="'.e($edit['funcao']??'').'"></label><button>Salvar usuario</button></form><section class="card"><div class="toolbar"><input class="table-search" data-target="users-table" placeholder="Pesquisar usuarios"></div><div class="table-responsive"><table id="users-table" class="table data-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Departamento</th><th></th></tr></thead><tbody>';foreach($rows as $u)echo '<tr><td>'.e($u['nome']).'</td><td>'.e($u['email']).'</td><td>'.e(role_label($u['perfil'])).'</td><td>'.e($u['departamento']).'</td><td><a class="mini" href="index.php?page=usuarios&id='.e($u['id']).'">Editar</a></td></tr>';echo '</tbody></table></div></section></section>';return true;}
 if($page==='rh-dashboard'){if($profile!=='rh')redirect('dashboard');$rows=db()->query('SELECT a.codigo,a.nome,c.nome categoria,a.quantidade_atual FROM ativos a LEFT JOIN categorias c ON c.id=a.categoria_id ORDER BY a.nome')->fetchAll();echo '<h1>Painel RH</h1><section class="card"><p class="muted">Consulta de equipamentos e disponibilidade.</p>';table_view($rows);echo '</section>';return true;}
 if($page==='requisicoes-ti'){
    if($profile!=='coordenacao_ti') redirect('dashboard');
    $stmt=db()->query("SELECT r.id,r.codigo_requisicao,r.nome solicitante,r.departamento,r.descricao,r.status,r.aprovado_por,a.codigo,a.nome ativo,c.nome categoria,a.quantidade_atual FROM requisicoes r LEFT JOIN ativos a ON a.id=r.ativo_id LEFT JOIN categorias c ON c.id=a.categoria_id WHERE r.ativo_id IS NOT NULL ORDER BY r.id DESC");
    $rows=$stmt->fetchAll();
