        if($r['status']!=='Concluído' && $r['ativo']!==null){
            if((int)$r['quantidade_atual'] > 0) $action='<form method="post" action="index.php?page=concluir-requisicao-ti"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="id" value="'.e($r['id']).'"><button class="mini">Concluir solicitacao</button></form>';
            else $action='<span class="text-danger">Estoque indisponivel</span>';
        }
        echo '<tr><td>'.e($r['codigo_requisicao']).'</td><td>'.e($r['solicitante']).'</td><td>'.e($equipment).'</td><td>'.e($stock).'</td><td>'.render_status_badge($r['status']).'</td><td>'.e($r['aprovado_por']??'-').'</td><td>'.$action.'</td></tr>';
    }
    echo '</tbody></table></div></section>'; return true;
 }
 if($page==='qrcode'){
    if(!in_array($profile,['administrador','gestor'],true)) redirect('dashboard');
    [$scopeSql,$scopeParams]=categoria_scope_sql('a.categoria_id');
    $stmt=db()->prepare("SELECT a.id,a.codigo,a.nome,a.localizacao,c.nome categoria FROM ativos a LEFT JOIN categorias c ON c.id=a.categoria_id WHERE 1=1{$scopeSql} ORDER BY a.codigo");$stmt->execute($scopeParams);$rows=$stmt->fetchAll();
    global $config;
