    foreach($rows as $r){$url=rtrim($config['base_url'],'/').'/index.php?page=qr&codigo='.urlencode($r['codigo']);$qr='https://api.qrserver.com/v1/create-qr-code/?size=160x160&data='.urlencode($url);echo '<tr><td>'.e($r['codigo']).'</td><td>'.e($r['nome']).'</td><td>'.e($r['categoria']??'Sem categoria').'</td><td>'.e($r['localizacao']??'').'</td><td><img class="qr-img" src="'.e($qr).'" alt="QR Code de '.e($r['codigo']).'"></td><td><a class="mini" href="'.e($url).'" target="_blank" rel="noopener">Visualizar</a> <a class="mini" href="'.e($qr).'" target="_blank" rel="noopener">Imprimir QR Code</a></td></tr>';}
    echo '</tbody></table></div></section>';return true;
 }
 if(in_array($page,['it-dashboard','finance-dashboard','purchase-requests'],true)) { $expect=['it-dashboard'=>'coordenacao_ti','finance-dashboard'=>'financeiro'];if(isset($expect[$page])&&$profile!==$expect[$page])redirect('dashboard');if($page==='purchase-requests'&&$profile!=='administrador')redirect('dashboard');$rows=$page==='purchase-requests'?purchase_rows():($page==='it-dashboard'?purchase_rows(['PENDING_IT']):purchase_rows(['PENDING_FINANCE','PURCHASED','REJECTED']));$title=$page==='it-dashboard'?'Aprovacoes da Coordenacao TI':($page==='finance-dashboard'?'Financeiro':'Solicitacoes de Compra');echo '<h1>'.e($title).'</h1>'.($flash?'<div class="alert-success">'.e($flash).'</div>':'');if($page==='purchase-requests')echo '<section class="card"><h2>Nova solicitacao</h2><form method="post" action="index.php?page=purchase-request-save" class="asset-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><label>Produto<input name="product_name" required></label><label>Quantidade<input type="number" name="quantity" min="1" value="1" required></label><label>URL de compra<input type="url" name="purchase_url"></label><label>Prioridade<select name="priority"><option>Baixa</option><option selected>Normal</option><option>Alta</option><option>Urgente</option></select></label><label class="wide">Justificativa<textarea name="justification" required></textarea></label><button>Enviar a Coordenacao TI</button></form></section>';
 if($page==='finance-dashboard'){$all=purchase_rows();$k=['PURCHASED'=>'Compras concluidas','REJECTED'=>'Solicitacoes rejeitadas','PENDING_FINANCE'=>'Solicitacoes pendentes','ALL'=>'Total de solicitacoes'];echo '<section class="metrics">';foreach($k as $st=>$label){$cnt=$st==='ALL'?count($all):count(array_filter($all,fn($r)=>$r['status']===$st));echo '<a class="metric kpi-link" href="#" data-status="'.e($st).'"><span>'.e($label).'</span><strong>'.e($cnt).'</strong></a>';}echo '</section><section class="card"><div class="toolbar"><input class="table-search" data-target="finance-purchase-table" placeholder="Pesquisar"><select class="table-filter" data-target="finance-purchase-table" data-column="5"><option value="">Todos status</option><option>Pendente no Financeiro</option><option>Comprada</option><option>Rejeitada</option></select><input type="date" class="table-filter" data-target="finance-purchase-table" data-column="4"><input class="table-filter" data-target="finance-purchase-table" data-column="2" placeholder="Departamento"></div><div class="table-responsive"><table id="finance-purchase-table" class="table data-table"><thead><tr><th>ID</th><th>Solicitante</th><th>Departamento</th><th>Valor total</th><th>Data</th><th>Status</th></tr></thead><tbody>';foreach($all as $r){$total=(float)($r['quantity']??0);echo '<tr data-status="'.e($r['status']).'"><td>'.e($r['request_code']).'</td><td>'.e($r['requester_name']).'</td><td>'.e($r['departamento']??'').'</td><td>'.e(money_br($total)).'</td><td>'.e(date('Y-m-d',strtotime($r['created_at']))).'</td><td>'.e(purchase_status_label($r['status'])).'</td></tr>';}echo '</tbody></table></div></section>';}
 echo '<section class="card"><div class="toolbar"><input class="table-search" data-target="purchase-table" placeholder="Pesquisar solicitacoes"></div><div class="table-responsive"><table id="purchase-table" class="table table-hover data-table"><thead><tr><th>ID</th><th>Produto</th><th>Qtd.</th><th>Prioridade</th><th>Solicitante</th><th>Status</th><th>Acao</th></tr></thead><tbody>';foreach($rows as $r){$id=e($r['id']);$csrf=e(csrf());$action='<button type="button" class="mini" data-open-modal="timeline-'.$id.'">Historico</button>';if($page==='it-dashboard')$action='<form method="post" action="index.php?page=purchase-it-review"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="id" value="'.$id.'"><input name="comments" required placeholder="Comentario"><button class="mini" name="decision" value="approve">Aprovar</button><button class="mini danger" name="decision" value="reject">Rejeitar</button></form>';if($page==='finance-dashboard'&&$r['status']==='PENDING_FINANCE')$action='<form method="post" action="index.php?page=purchase-complete"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="id" value="'.$id.'"><input name="supplier" required placeholder="Fornecedor"><input name="invoice_number" required placeholder="Nota fiscal"><input type="date" name="purchase_date" required><input name="comments" placeholder="Comentario"><button class="mini">Concluir compra</button></form>';echo '<tr><td>'.e($r['request_code']).'</td><td>'.e($r['product_name']).'</td><td>'.e($r['quantity']).'</td><td>'.e($r['priority']).'</td><td>'.e($r['requester_name']).'</td><td>'.purchase_status_badge($r['status']).'</td><td>'.$action.'</td></tr>';}echo '</tbody></table></div></section>';foreach($rows as $r)echo '<div class="modal" id="timeline-'.e($r['id']).'" aria-hidden="true"><div class="modal-panel wide-modal"><button type="button" class="modal-close" data-close-modal>&times;</button><h2>Linha do tempo '.e($r['request_code']).'</h2>'.purchase_timeline((int)$r['id']).'</div></div>';return true; }
 if($page==='hiring'){if(!in_array($profile,['administrador','rh'],true))redirect('dashboard');echo '<h1>Contratacoes</h1>'.($flash?'<div class="alert-success">'.e($flash).'</div>':'');if($profile==='rh')echo '<section class="card"><form method="post" action="index.php?page=hiring-save" enctype="multipart/form-data" class="asset-form hiring-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><label>Cargo<input name="position" required></label><label>Departamento<input name="department" required></label><label>Data de inicio<input type="date" name="data_inicio" min="'.e((new DateTime('today'))->modify('+7 days')->format('Y-m-d')).'" required></label><label>Documento de admissao (.pdf, .docx)<input type="file" name="admission_document" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required></label><div class="wide hiring-people"><div class="hiring-people-header"><h2>Pessoas para contratacao</h2><button type="button" id="add-hiring-person" class="mini secondary">Adicionar contratacao</button></div><div id="hiring-people-list"></div></div><button>Enviar solicitacao</button></form></section>';if($profile==='administrador'){$rows=db()->query('SELECT h.*,u.nome requester_name FROM hiring_requests h LEFT JOIN usuarios u ON u.id=h.created_by ORDER BY h.id DESC')->fetchAll();echo '<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Cargo</th><th>Departamento</th><th>Pessoas</th><th>Data de inicio</th><th>Documento de admissao</th><th>Data de criacao</th><th>Status</th><th>Acoes</th></tr></thead><tbody>';foreach($rows as $r){$doc=$r['admission_document']?'<a class="mini secondary" target="_blank" href="'.e($r['admission_document']).'">Visualizar/Baixar</a>':'';$actions=$r['status']==='Em análise'?'<form method="post" action="index.php?page=hiring-review"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="id" value="'.e($r['id']).'"><button class="mini" name="decision" value="approve">Aprovar</button><button class="mini danger" name="decision" value="reject">Recusar</button></form>':''; $people=json_decode($r['candidate_names'] ?? '[]', true); if(!is_array($people) || !$people)$people=[]; $peopleText=$people?implode(', ', $people):(($r['quantity'] ?? 0).' pessoa(s)'); $dataInicioFmt=$r['data_inicio']?e(date('d/m/Y',strtotime($r['data_inicio']))):'-'; echo '<tr><td>'.e($r['position']).'</td><td>'.e($r['department']).'</td><td>'.e($peopleText).'</td><td>'.$dataInicioFmt.'</td><td>'.$doc.'</td><td>'.e(date('d/m/Y H:i',strtotime($r['created_at']))).'</td><td>'.hiring_status_badge($r['status']).'</td><td>'.$actions.'</td></tr>';}echo '</tbody></table></div></section>';}return true;}
 if(in_array($page,['inventory','inventory-reports'],true)){if($profile!=='administrador')redirect('dashboard');if($page==='inventory-reports'){$m=db()->query('SELECT a.codigo,a.nome,b.opening_stock,b.counted,b.balance FROM inventory_balances b JOIN ativos a ON a.id=b.ativo_id WHERE b.balance<0')->fetchAll();echo '<h1>Relatorios de Inventario</h1><section class="card"><h2>Ativos faltantes</h2>';table_view($m);echo '</section>';return true;}$s=db()->query("SELECT id FROM inventory_sessions WHERE status='OPEN' LIMIT 1")->fetch();echo '<h1>Inventario</h1>'.($flash?'<div class="alert-success">'.e($flash).'</div>':'');if(!$s){echo '<section class="card"><form method="post" action="index.php?page=inventory-start"><input type="hidden" name="csrf" value="'.e(csrf()).'"><button>Iniciar inventario</button></form></section>';return true;}$q=db()->prepare('SELECT a.codigo,a.nome,b.opening_stock,b.counted,b.balance FROM inventory_balances b JOIN ativos a ON a.id=b.ativo_id WHERE b.inventory_session_id=?');$q->execute([$s['id']]);echo '<section class="card"><form method="post" action="index.php?page=inventory-scan"><input type="hidden" name="csrf" value="'.e(csrf()).'"><label>QR Code ou ID<input name="asset_code" required autofocus></label><button>Registrar leitura</button></form><form method="post" action="index.php?page=inventory-finish"><input type="hidden" name="csrf" value="'.e(csrf()).'"><button class="secondary">Finalizar</button></form></section><section class="card">';table_view($q->fetchAll());echo '</section>';return true;}
 return false;
